"""Dependency-free projected 3D concept galaxy; no tracking or external scripts."""
import json

def space_html(terms,links):
    data=json.dumps({'nodes':[{'id':i,'name':t[1],'category':t[0],'meaning':t[3],'impact':t[4]} for i,t in enumerate(terms)],'edges':links},ensure_ascii=False).replace('<','\\u003c')
    return '''<!doctype html><html lang="ko"><meta charset="utf-8"><style>
*{box-sizing:border-box}body{margin:0;font:14px Pretendard,'Malgun Gothic',sans-serif;color:#e6ebf5;background:#090d19;border-radius:16px;overflow:hidden}header{display:flex;gap:8px;align-items:center;padding:16px;flex-wrap:wrap;background:#101729;border-bottom:1px solid #ffffff12}select,button{font:inherit;color:#e6ebf5;background:#1c2740;border:1px solid #374564;padding:8px 12px;border-radius:8px;cursor:pointer}select{max-width:310px}button:hover{background:#2a3855}button:focus-visible,select:focus-visible{outline:2px solid #ffb58b;outline-offset:3px}.stage{height:490px;position:relative;background:radial-gradient(ellipse at 25% 30%,#47337345,transparent 50%),radial-gradient(ellipse at 75% 65%,#153d6645,transparent 55%),#090d19}svg{width:100%;height:100%;touch-action:none;cursor:grab}svg:active{cursor:grabbing}.edge{stroke:#93a8ce;stroke-opacity:.19;stroke-width:1}.edge.hot{stroke:#ffc19b;stroke-opacity:.85;stroke-width:1.8}.edge-hit{stroke:transparent;stroke-width:14;cursor:help}.node{cursor:pointer;outline:none}.node:hover circle,.node:focus circle{stroke:#fff;stroke-width:2.5}text{font-family:inherit;pointer-events:none;paint-order:stroke;stroke:#090d19;stroke-width:4px;stroke-linejoin:round}.detail{min-height:100px;padding:14px 20px;line-height:1.65;background:#101729;border-top:1px solid #ffffff12;color:#c8d3e8}.detail b{color:#fff}.hint{font-size:12px;color:#aab8d1;padding:0 18px 14px;background:#101729}.tip{display:none;position:fixed;z-index:10;pointer-events:none;background:#172239f5;border:1px solid #52617d;color:#edf3ff;border-radius:10px;padding:12px;max-width:300px;font-size:13px;line-height:1.65;box-shadow:0 8px 24px #0008}button[aria-pressed=true]{border-color:#ffa86f;color:#ffd1b3}small{color:#9baac5}
</style><header><label for="concept">중심 개념</label><select id="concept"></select><button id="dimension" aria-pressed="false">2D 보기</button><button id="motion" aria-pressed="false">회전 시작</button><button id="reset">시점 초기화</button></header><div class="stage"><svg id="space" viewBox="0 0 1000 490" role="group" aria-label="우주 형태의 경제 개념 지도"></svg><div id="tip" class="tip"></div></div><div class="detail" id="detail" aria-live="polite"></div><div class="hint">드래그 회전 · 휠 확대 · 개념 클릭으로 연결 강조 · 연결선 클릭으로 관계 설명 · 키보드 Tab/Enter 지원<br>개념 간 관계는 조건부 해석이며 현재 시장에서의 인과관계를 확정하지 않습니다.</div><script>
const data=PAYLOAD,svg=document.querySelector('#space'),select=document.querySelector('#concept'),detail=document.querySelector('#detail'),tip=document.querySelector('#tip'),ns='http://www.w3.org/2000/svg';
const palette={'물가':'#ffba8c','금리·채권':'#bba6ff','경기·고용':'#80dfbf','무역·통화':'#80c8ff','시장':'#ffa9d0','읽는 법':'#ffe49a'};
let focus=0,angle=.3,tilt=.15,zoom=1,flat=false,spin=false,down=null,moved=false,last=0,projected=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function el(tag,attrs,parent=svg){let e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));parent.append(e);return e}
const defs=el('defs',{}),glow=el('filter',{id:'glow',x:'-100%',y:'-100%',width:'300%',height:'300%'},defs);el('feGaussianBlur',{stdDeviation:5},glow);
const stars=el('g',{'aria-hidden':true});for(let i=0;i<110;i++)el('circle',{cx:(i*173+37)%1000,cy:(i*97+23)%490,r:i%8===0?1.4:.65,fill:'#d4e5ff',opacity:.15+(i%5)*.10},stars);
const orbit=el('ellipse',{cx:500,cy:245,rx:365,ry:112,fill:'none',stroke:'#9b9de3','stroke-opacity':.13,'stroke-dasharray':'2 8','aria-hidden':true});
const lineLayer=el('g',{}),nodeLayer=el('g',{}),edges=[],nodes=[];
data.edges.forEach(e=>{let line=el('line',{class:'edge'},lineLayer),hit=el('line',{class:'edge-hit',tabindex:0,role:'button','aria-label':data.nodes[e[0]].name+' → '+data.nodes[e[1]].name+'：'+e[2]},lineLayer);function relation(){detail.replaceChildren();let b=document.createElement('b');b.textContent=data.nodes[e[0]].name+' → '+data.nodes[e[1]].name+' / '+e[2];detail.append(b,document.createElement('br'),document.createTextNode(e[3]))}hit.onclick=relation;hit.onfocus=relation;hit.onkeydown=v=>{if(v.key==='Enter')relation()};hit.onmousemove=v=>show(v,e[2],e[3]);hit.onmouseleave=hide;edges.push({e,line,hit})});
data.nodes.forEach((n,i)=>{let option=document.createElement('option');option.value=i;option.textContent=n.name;select.append(option);let group=el('g',{class:'node',tabindex:0,role:'button','aria-label':n.name},nodeLayer);let aura=el('circle',{r:22,fill:palette[n.category],opacity:.2,filter:'url(#glow)'},group),circle=el('circle',{r:7,fill:palette[n.category],stroke:palette[n.category],'stroke-width':1},group),label=el('text',{x:13,y:4,fill:'#e5ecfa','font-size':11},group);label.textContent=n.name;function choose(){if(moved)return;focus=i;select.value=i;explain();draw()}group.onclick=choose;group.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();moved=false;choose()}};group.onfocus=()=>{detail.textContent=n.name+'：'+n.meaning};group.onmousemove=e=>show(e,n.name,n.meaning);group.onmouseleave=hide;nodes.push({n,group,aura,circle,label})});
function show(e,title,body){tip.replaceChildren();let b=document.createElement('b');b.textContent=title;tip.append(b,document.createElement('br'),document.createTextNode(body));tip.style.display='block';tip.style.left=Math.max(8,Math.min(e.clientX+12,innerWidth-310))+'px';tip.style.top=Math.max(8,Math.min(e.clientY+12,innerHeight-170))+'px'}function hide(){tip.style.display='none'}
function explain(){detail.replaceChildren();let b=document.createElement('b'),n=data.nodes[focus];b.textContent=n.name;detail.append(b,document.createElement('br'),document.createTextNode(n.meaning+' '+n.impact))}
function draw(){let neighbors=new Set([focus,...data.edges.filter(e=>e[0]===focus||e[1]===focus).flatMap(e=>[e[0],e[1]])]);projected=data.nodes.map((n,i)=>{let p=i*2.399963,y=1-2*(i+.5)/data.nodes.length,r=Math.sqrt(1-y*y),x=r*Math.cos(p)*310,z=r*Math.sin(p)*310;let yy=y*185,xx=x*Math.cos(angle)-z*Math.sin(angle),zz=x*Math.sin(angle)+z*Math.cos(angle),rotY=yy*Math.cos(tilt)-zz*Math.sin(tilt);zz=yy*Math.sin(tilt)+zz*Math.cos(tilt);let depth=flat?1:720/(720+zz);return {x:500+xx*depth*zoom,y:245+(flat?yy:rotY)*depth*zoom,d:depth,z:zz}});edges.forEach(({e,line,hit})=>{let a=projected[e[0]],b=projected[e[1]];for(let item of [line,hit])for(let [k,v] of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))item.setAttribute(k,v);line.setAttribute('class','edge'+(e[0]===focus||e[1]===focus?' hot':''))});nodes.forEach(({n,group,aura,circle,label},i)=>{let p=projected[i],active=i===focus,near=neighbors.has(i);group.setAttribute('transform',`translate(${p.x},${p.y})`);group.setAttribute('opacity',near?1:.38);circle.setAttribute('r',active?13:Math.max(4,7*p.d));aura.setAttribute('r',active?29:18*p.d);label.setAttribute('font-size',active?14:near?12:10);label.setAttribute('font-weight',active?700:500);label.setAttribute('x',active?19:12);group.setAttribute('aria-pressed',active?'true':'false')});[...nodes].sort((a,b)=>projected[b.n.id].z-projected[a.n.id].z).forEach(n=>nodeLayer.append(n.group))}
svg.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];moved=false;spin=false;updateMotion()});svg.addEventListener('pointermove',e=>{if(!down)return;let dx=e.clientX-down[0],dy=e.clientY-down[1];if(Math.abs(dx)+Math.abs(dy)>3)moved=true;angle+=dx*.005;tilt=Math.max(-1.1,Math.min(1.1,tilt+dy*.004));down=[e.clientX,e.clientY];hide();draw()});window.addEventListener('pointerup',()=>{down=null});svg.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.min(1.7,Math.max(.55,zoom-e.deltaY*.001));hide();draw()},{passive:false});
select.onchange=()=>{focus=Number(select.value);explain();draw()};document.querySelector('#dimension').onclick=e=>{flat=!flat;e.target.textContent=flat?'3D 보기':'2D 보기';e.target.setAttribute('aria-pressed',String(flat));draw()};function updateMotion(){let b=document.querySelector('#motion');b.textContent=spin?'회전 멈춤':'회전 시작';b.setAttribute('aria-pressed',String(spin))}document.querySelector('#motion').onclick=()=>{spin=!spin;updateMotion()};document.querySelector('#reset').onclick=()=>{angle=.3;tilt=.15;zoom=1;draw()};document.addEventListener('visibilitychange',()=>{if(document.hidden){spin=false;updateMotion()}});function animate(t){if(spin&&!document.hidden&&t-last>33){angle+=.002;draw();last=t}requestAnimationFrame(animate)}explain();draw();requestAnimationFrame(animate);if(!reduced){spin=true;updateMotion();setTimeout(()=>{spin=false;updateMotion()},2200)}
</script></html>'''.replace('PAYLOAD',data)
